@Override // java.lang.Thread, java.lang.Runnable
public void run() {
    final int iChangeLanPassSync = 0;
    for (int i = 0; i < 2 && this.mThreadId == LanDeviceSetPasswordFragment.this.mSetLanPasswordThreadId; i++) {
        iChangeLanPassSync = LoginHelper.changeLanPassSync(this.mLoginHandle, this.oldPassword, this.newPassword);
        if (this.mThreadId != LanDeviceSetPasswordFragment.this.mSetLanPasswordThreadId || iChangeLanPassSync != 1104) {
            break;
        }
        KeyExchangeLanResult keyExchangeLanResultKeyExchangeByLanSync = LoginHelper.keyExchangeByLanSync(this.mLoginHandle.getStrLanIP(), this.mLoginHandle.getnPort(), this.oldPassword);
        if (keyExchangeLanResultKeyExchangeByLanSync.getResult() == 1000) {
            this.mLoginHandle.setSid(keyExchangeLanResultKeyExchangeByLanSync.getSid());
            this.mLoginHandle.setsKey(keyExchangeLanResultKeyExchangeByLanSync.getsKey());
            this.mLoginHandle.setPermission(keyExchangeLanResultKeyExchangeByLanSync.getPerm());
        } else {
            iChangeLanPassSync = keyExchangeLanResultKeyExchangeByLanSync.getResult();
            break;
        }
    }
    if (this.mThreadId != LanDeviceSetPasswordFragment.this.mSetLanPasswordThreadId) {
        return;
    }
    LogUtil.d(LanDeviceSetPasswordFragment.TAG, "<redacted literal>" + iChangeLanPassSync);
    if (iChangeLanPassSync == 256) {
        LanDeviceSetPasswordFragment.this.mDeviceInfo.setStrPassword(this.newPassword);
        if (LanDeviceSetPasswordFragment.this.mStartType == 1) {
            LogUtil.d(LanDeviceSetPasswordFragment.TAG, "<redacted literal>" + DeviceManager.getInstance().updateLanDevicePassword(this.mLoginHandle.getnDeviceID(), this.newPassword));
        } else {
            LogUtil.d(LanDeviceSetPasswordFragment.TAG, "<redacted literal>" + DeviceManager.getInstance().updateLanDevicePassword(this.mLoginHandle.getnDeviceID(), this.newPassword));
        }
    }
    LanDeviceSetPasswordFragment.this.mBaseFragmentHandler.post(new Runnable() { // from class: com.macrovideo.v380.fragments.LanDeviceSetPasswordFragment.SetLanPasswordThread.1
        @Override // java.lang.Runnable
        public void run() {
            if (SetLanPasswordThread.this.mThreadId != LanDeviceSetPasswordFragment.this.mSetLanPasswordThreadId) {
                return;
            }
            LanDeviceSetPasswordFragment.this.mActivity.dismissLoadingDialog();
            int i2 = iChangeLanPassSync;
            if (i2 == -257) {
                LanDeviceSetPasswordFragment.this.mActivity.showToast(R.string.str_notice_result_neterror, new int[0]);
                return;
            }
            if (i2 != 256) {
                LanDeviceSetPasswordFragment.this.mActivity.showToast(R.string.str_setting_failure, new int[0]);
                return;
            }
            if (LanDeviceSetPasswordFragment.this.mStartType == 1) {
                if (LanDeviceSetPasswordFragment.this.mActivity instanceof AddDeviceActivity) {
                    ((AddDeviceActivity) LanDeviceSetPasswordFragment.this.mActivity).gotoLanDeviceHomePage(SetLanPasswordThread.this.mLoginHandle.getnDeviceID());
                    return;
                }
                return;
            }
            if (LanDeviceSetPasswordFragment.this.mStartType == 3) {
                Intent intent = new Intent(LanDeviceSetPasswordFragment.this.mActivity, (Class<?>) HomePageActivity.class);
                intent.putExtra(GlobalDefines.KEY_REFRESH_LIST, true);
                intent.putExtra(GlobalDefines.KEY_REFRESH_LIST_SINGLE_ITEM_DEVICEID, LanDeviceSetPasswordFragment.this.mDeviceInfo.getnDevID());
                intent.putExtra(GlobalDefines.KEY_REFRESH_LIST_SINGLE_ITEM_DEVICE_USERNAME, LanDeviceSetPasswordFragment.this.mDeviceInfo.getStrUsername());
                intent.putExtra(GlobalDefines.KEY_REFRESH_LIST_SINGLE_ITEM_DEVICE_PASSWORD, LanDeviceSetPasswordFragment.this.mDeviceInfo.getStrPassword());
                intent.putExtra(GlobalDefines.KEY_REFRESH_LIST_SINGLE_ITEM_DEVICE_NICKNAME, LanDeviceSetPasswordFragment.this.mDeviceInfo.getStrName());
                intent.putExtra(GlobalDefines.KEY_REFRESH_LIST_DEVICE_MODEL, LanDeviceSetPasswordFragment.this.mDeviceInfo.getDeviceModel());
                intent.putExtra(GlobalDefines.KEY_REFRESH_LIST_GROUP_ID, LanDeviceSetPasswordFragment.this.mDeviceInfo.getnGroupId());
                intent.putExtra(GlobalDefines.KEY_REFRESH_LIST_AFTER_MODIFY_DEVICE, true);
                intent.putExtra(GlobalDefines.KEY_REFRESH_LIST_IS_LAN_PASS_MODE, true);
                intent.putExtra(GlobalDefines.KEY_AUTO_LOGIN_DEVICE, true);
                intent.putExtra(GlobalDefines.KEY_AUTO_LOGIN_DEVICE_TYPE, LanDeviceSetPasswordFragment.this.mLoginType);
                LanDeviceSetPasswordFragment.this.mActivity.startActivity(intent);
                LanDeviceSetPasswordFragment.this.mActivity.finish();
                return;
            }
            Intent intent2 = new Intent(LanDeviceSetPasswordFragment.this.mActivity, (Class<?>) HomePageActivity.class);
            intent2.putExtra(GlobalDefines.KEY_REFRESH_LIST, true);
            intent2.putExtra(GlobalDefines.KEY_REFRESH_LIST_SINGLE_ITEM_DEVICEID, LanDeviceSetPasswordFragment.this.mDeviceInfo.getnDevID());
            intent2.putExtra(GlobalDefines.KEY_REFRESH_LIST_SINGLE_ITEM_DEVICE_USERNAME, LanDeviceSetPasswordFragment.this.mDeviceInfo.getStrUsername());
            intent2.putExtra(GlobalDefines.KEY_REFRESH_LIST_SINGLE_ITEM_DEVICE_PASSWORD, LanDeviceSetPasswordFragment.this.mDeviceInfo.getStrPassword());
            intent2.putExtra(GlobalDefines.KEY_REFRESH_LIST_SINGLE_ITEM_DEVICE_NICKNAME, LanDeviceSetPasswordFragment.this.mDeviceInfo.getStrName());
            intent2.putExtra(GlobalDefines.KEY_REFRESH_LIST_DEVICE_MODEL, LanDeviceSetPasswordFragment.this.mDeviceInfo.getDeviceModel());
            intent2.putExtra(GlobalDefines.KEY_REFRESH_LIST_GROUP_ID, LanDeviceSetPasswordFragment.this.mDeviceInfo.getnGroupId());
            intent2.putExtra(GlobalDefines.KEY_REFRESH_LIST_AFTER_MODIFY_DEVICE, true);
            intent2.putExtra(GlobalDefines.KEY_REFRESH_LIST_IS_LAN_PASS_MODE, true);
            LanDeviceSetPasswordFragment.this.mActivity.startActivity(intent2);
            LanDeviceSetPasswordFragment.this.mActivity.finish();
        }
    });
}
